do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero) values ($q$UBER$q$,$q$Uber Technologies$q$,$q$consumer$q$,$q$large$q$,true,true),($q$AAPL$q$,$q$Apple$q$,$q$consumer$q$,$q$large$q$,true,false),($q$META$q$,$q$Meta Platforms$q$,$q$consumer$q$,$q$large$q$,true,false),($q$MSFT$q$,$q$Microsoft$q$,$q$business$q$,$q$large$q$,true,false),($q$PLTR$q$,$q$Palantir Technologies$q$,$q$business$q$,$q$large$q$,true,false),($q$NVDA$q$,$q$NVIDIA$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$TSM$q$,$q$Taiwan Semiconductor Manufacturing$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$AMD$q$,$q$Advanced Micro Devices$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$DASH$q$,$q$DoorDash$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$NET$q$,$q$Cloudflare$q$,$q$business$q$,$q$mid$q$,true,false),($q$CRWV$q$,$q$CoreWeave$q$,$q$infrastructure$q$,$q$mid$q$,true,true),($q$CBRS$q$,$q$Cerebras Systems$q$,$q$infrastructure$q$,$q$mid$q$,true,false),($q$NBIS$q$,$q$Nebius Group$q$,$q$infrastructure$q$,$q$mid$q$,true,false),($q$LYFT$q$,$q$Lyft$q$,$q$consumer$q$,$q$small$q$,true,true),($q$APLD$q$,$q$Applied Digital$q$,$q$infrastructure$q$,$q$small$q$,true,false),($q$AMZN$q$,$q$Amazon$q$,$q$consumer$q$,$q$large$q$,true,false),($q$GOOGL$q$,$q$Alphabet$q$,$q$consumer$q$,$q$large$q$,true,false),($q$TSLA$q$,$q$Tesla$q$,$q$consumer$q$,$q$large$q$,true,false),($q$ORCL$q$,$q$Oracle$q$,$q$business$q$,$q$large$q$,true,false),($q$INTC$q$,$q$Intel$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$LCID$q$,$q$Lucid$q$,$q$consumer$q$,$q$small$q$,true,false),($q$LIME$q$,$q$Lime$q$,$q$consumer$q$,$q$small$q$,true,false),($q$CART$q$,$q$Instacart$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$GRAB$q$,$q$Grab$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$AUR$q$,$q$Aurora$q$,$q$business$q$,$q$small$q$,true,false) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero;
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Giphy$q$,$q$private_company$q$),($q$Instagram$q$,$q$private_company$q$),($q$TikTok$q$,$q$private_company$q$),($q$WhatsApp$q$,$q$private_company$q$),($q$Within Unlimited$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$Beginning in 2020, we became subject to a lawsuit by the FTC alleging that we violated antitrust laws, including by acquiring Instagram in 2012 and WhatsApp in 2014.$q$),(2,$q$For example, each of Apple and Google have integrated competitive products with iOS and Android, respectively.$q$),(3,$q$For example, we are currently the subject of multiple putative class action suits in connection with our platform and user data practices and the misuse of certain data by a developer that shared such data with third parties in violation of our terms and policies; the disclosure of our earnings results for the second quarter of 2018; our acquisitions of Instagram and WhatsApp, as well as other alleged anticompetitive conduct; a former employee's allegations and release of internal company documents beginning in September 2021; the disclosure of our earnings results for the fourth quarter of 2021; and allegations that we inflated our estimates of the potential audience size for advertisements, resulting in artificially increased demand and higher prices.$q$),(4,$q$For example, we completed our divestiture of Giphy in 2023 following the United Kingdom Competition and Markets Authority's order directing us to divest Giphy post-acquisition.$q$),(5,$q$In addition, although we were able to successfully complete the acquisition after prevailing in federal court, the FTC sought to enjoin our proposed acquisition of Within Unlimited.$q$),(6,$q$User growth and engagement are also impacted by a number of other factors, including competitive products and services, such as TikTok, that have reduced some users' engagement with our products and services, as well as global and regional business, macroeconomic, and geopolitical conditions.$q$),(7,$q$including by acquiring Instagram in 2012 and WhatsApp in 2014 and by maintaining conditions on access to our platform.$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$competes$q$,$q$META$q$,$q$TikTok$q$,$q${6}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(2,$q$competes$q$,$q$META$q$,$q$Alphabet$q$,$q${2}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(3,$q$acquires$q$,$q$META$q$,$q$Giphy$q$,$q${4}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(4,$q$acquires$q$,$q$META$q$,$q$Within Unlimited$q$,$q${5}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(5,$q$acquires$q$,$q$META$q$,$q$Instagram$q$,$q${3,1,7}$q$::int[],$q${risk_factors,risk_factors,notes}$q$::text[],null,null,null,null),(6,$q$acquires$q$,$q$META$q$,$q$WhatsApp$q$,$q${1,7}$q$::int[],$q${risk_factors,notes}$q$::text[],null,null,null,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Uber$q$ then ticker=$q$UBER$q$ when $q$Alphabet$q$ then ticker=$q$GOOGL$q$ when $q$Microsoft$q$ then ticker=$q$MSFT$q$ when $q$NVIDIA$q$ then ticker=$q$NVDA$q$ when $q$Tesla$q$ then ticker=$q$TSLA$q$ when $q$META$q$ then ticker=$q$META$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,cost_usd,status,review_status) values ('filings_extraction','batch',$q$META 10-K M6 (staged)$q$,'claude-sonnet-5-5 via Claude Code session',0.7635,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; isnew := false; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; isnew := true; end if; if isnew then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1326801/000162828026003942/meta-20251231.htm$q$,r.sec[k],t,true,$q$2026-01-29$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
